INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('circuit-builder','basic','What is Ohm''s Law?',ARRAY['V = IR','V = I/R','V = IR²','V = I²R'],0,'Ohm''s Law: Voltage = Current × Resistance.',10),
('circuit-builder','basic','What is the unit of resistance?',ARRAY['Ohm (Ω)','Volt (V)','Ampere (A)','Watt (W)'],0,'Resistance is measured in ohms.',10),
('circuit-builder','basic','What is the unit of current?',ARRAY['Ampere (A)','Volt (V)','Ohm (Ω)','Farad (F)'],0,'Current is measured in amperes.',10),
('circuit-builder','basic','What is the unit of voltage?',ARRAY['Volt (V)','Ampere (A)','Ohm (Ω)','Joule (J)'],0,'Voltage is measured in volts.',10),
('circuit-builder','basic','What is the unit of power?',ARRAY['Watt (W)','Volt (V)','Ampere (A)','Ohm (Ω)'],0,'Power is measured in watts.',10),
('circuit-builder','basic','What is the power formula?',ARRAY['P = VI','P = V/I','P = I/V','P = V+I'],0,'Power = Voltage × Current.',10),
('circuit-builder','basic','What is the resistance of two 10Ω resistors in series?',ARRAY['20Ω','5Ω','10Ω','100Ω'],0,'Series: R = R1 + R2 = 20Ω.',10),
('circuit-builder','basic','What is the resistance of two 10Ω resistors in parallel?',ARRAY['5Ω','20Ω','10Ω','100Ω'],0,'Parallel: R = (R1×R2)/(R1+R2) = 5Ω.',10),
('circuit-builder','basic','What happens to current in a series circuit?',ARRAY['Same at all points','Splits at each component','Increases','Decreases'],0,'Current is constant in a series circuit.',10),
('circuit-builder','basic','What happens to voltage in a parallel circuit?',ARRAY['Same across all branches','Splits across branches','Increases','Decreases'],0,'Voltage is equal across parallel branches.',10),
('circuit-builder','basic','What is Kirchhoff''s Voltage Law (KVL)?',ARRAY['Sum of voltages around a loop = 0','Sum of currents = 0','V = IR','P = VI'],0,'KVL: algebraic sum of voltages in a loop is zero.',10),
('circuit-builder','basic','What is Kirchhoff''s Current Law (KCL)?',ARRAY['Sum of currents at a node = 0','Sum of voltages = 0','I = V/R','P = I²R'],0,'KCL: sum of currents entering a node equals sum leaving.',10),
('circuit-builder','basic','What is a short circuit?',ARRAY['Zero resistance path','High resistance path','Open circuit','Normal circuit'],0,'Short circuit has near-zero resistance.',10),
('circuit-builder','basic','What is an open circuit?',ARRAY['Infinite resistance path','Zero resistance path','Low resistance path','Normal circuit'],0,'Open circuit has infinite resistance.',10),
('circuit-builder','basic','What is the equivalent resistance of 5Ω and 15Ω in series?',ARRAY['20Ω','3.75Ω','10Ω','75Ω'],0,'Series: 5 + 15 = 20Ω.',10),
('circuit-builder','basic','What is the equivalent resistance of 6Ω and 3Ω in parallel?',ARRAY['2Ω','9Ω','18Ω','3Ω'],0,'Parallel: (6×3)/(6+3) = 2Ω.',10),
('circuit-builder','basic','What does a capacitor do in a DC circuit?',ARRAY['Blocks DC after charging','Passes DC freely','Acts as a short','Acts as a resistor'],0,'Capacitor charges then blocks DC (open circuit).',10),
('circuit-builder','basic','What does an inductor do in a DC circuit?',ARRAY['Acts as a short after steady state','Blocks DC','Acts as open circuit','Acts as a capacitor'],0,'Inductor passes DC after transient (short circuit).',10),
('circuit-builder','basic','What is the unit of capacitance?',ARRAY['Farad (F)','Henry (H)','Ohm (Ω)','Volt (V)'],0,'Capacitance is measured in farads.',10),
('circuit-builder','basic','What is the unit of inductance?',ARRAY['Henry (H)','Farad (F)','Ohm (Ω)','Ampere (A)'],0,'Inductance is measured in henries.',10),
('circuit-builder','basic','What is the formula for capacitive reactance?',ARRAY['Xc = 1/(2πfC)','Xc = 2πfC','Xc = 1/(2πfL)','Xc = 2πfL'],0,'Capacitive reactance decreases with frequency.',10),
('circuit-builder','basic','What is the formula for inductive reactance?',ARRAY['Xl = 2πfL','Xl = 1/(2πfL)','Xl = 2πfC','Xl = 1/(2πfC)'],0,'Inductive reactance increases with frequency.',10),
('circuit-builder','basic','What happens to a capacitor''s reactance as frequency increases?',ARRAY['Decreases','Increases','Stays same','Becomes zero'],0,'Xc = 1/(2πfC) → decreases with f.',10),
('circuit-builder','basic','What happens to an inductor''s reactance as frequency increases?',ARRAY['Increases','Decreases','Stays same','Becomes zero'],0,'Xl = 2πfL → increases with f.',10),
('circuit-builder','basic','What is the time constant of an RC circuit?',ARRAY['τ = RC','τ = R/C','τ = C/R','τ = R+C'],0,'Time constant = R × C.',10),
('circuit-builder','basic','What is the time constant of an RL circuit?',ARRAY['τ = L/R','τ = R/L','τ = RL','τ = R+L'],0,'Time constant = L / R.',10),
('circuit-builder','basic','What is the voltage across a capacitor after one time constant during charging?',ARRAY['63.2% of V','37% of V','100% of V','50% of V'],0,'Capacitor charges to 63.2% after one τ.',10),
('circuit-builder','basic','What is the voltage across a capacitor after one time constant during discharging?',ARRAY['36.8% of V','63.2% of V','0% of V','50% of V'],0,'Capacitor discharges to 36.8% after one τ.',10),
('circuit-builder','basic','How many time constants to fully charge a capacitor?',ARRAY['5','3','1','10'],0,'~99.3% charged after 5 time constants.',10),
('circuit-builder','basic','What is a node in a circuit?',ARRAY['Junction of two or more elements','A single element','A loop','A battery'],0,'A node is a connection point.',10),
('circuit-builder','basic','What is a mesh in a circuit?',ARRAY['A loop with no inner loops','Any loop','A node','A branch'],0,'A mesh is the simplest loop.',10),
('circuit-builder','basic','What is a branch in a circuit?',ARRAY['A path between two nodes','A loop','A node','A source'],0,'A branch is a single path between nodes.',10),
('circuit-builder','basic','What is the current through a 10Ω resistor with 20V across it?',ARRAY['2A','0.5A','200A','10A'],0,'I = V/R = 20/10 = 2A.',10),
('circuit-builder','basic','What is the voltage across a 5Ω resistor with 3A through it?',ARRAY['15V','1.67V','8V','5V'],0,'V = IR = 3×5 = 15V.',10),
('circuit-builder','basic','What is the power dissipated by a 10Ω resistor with 2A through it?',ARRAY['40W','20W','10W','4W'],0,'P = I²R = 4×10 = 40W.',10),
('circuit-builder','basic','What is the power dissipated by a 10Ω resistor with 10V across it?',ARRAY['10W','1W','100W','0.1W'],0,'P = V²/R = 100/10 = 10W.',10),
('circuit-builder','basic','What is the equivalent capacitance of two 10µF caps in series?',ARRAY['5µF','20µF','10µF','100µF'],0,'Series caps: C = (C1×C2)/(C1+C2) = 5µF.',10),
('circuit-builder','basic','What is the equivalent capacitance of two 10µF caps in parallel?',ARRAY['20µF','5µF','10µF','100µF'],0,'Parallel caps: C = C1 + C2 = 20µF.',10),
('circuit-builder','basic','What is the equivalent inductance of two 10mH inductors in series?',ARRAY['20mH','5mH','10mH','100mH'],0,'Series inductors: L = L1 + L2 = 20mH.',10),
('circuit-builder','basic','What is the equivalent inductance of two 10mH inductors in parallel?',ARRAY['5mH','20mH','10mH','100mH'],0,'Parallel inductors: L = (L1×L2)/(L1+L2) = 5mH.',10),
('circuit-builder','basic','What is a voltage divider?',ARRAY['Two resistors splitting voltage','Two resistors combining voltage','A capacitor divider','An inductor divider'],0,'Voltage divider: Vout = Vin × R2/(R1+R2).',10),
('circuit-builder','basic','What is the output of a voltage divider with R1=R2=10Ω and Vin=12V?',ARRAY['6V','12V','3V','0V'],0,'Vout = 12 × 10/(10+10) = 6V.',10),
('circuit-builder','basic','What is a current divider?',ARRAY['Two parallel resistors splitting current','Two series resistors','A voltage divider','A transformer'],0,'Current divides inversely to resistance in parallel.',10),
('circuit-builder','basic','What is the current through R1=2Ω in parallel with R2=4Ω with total current 6A?',ARRAY['4A','2A','3A','6A'],0,'I1 = I × R2/(R1+R2) = 6 × 4/6 = 4A.',10),
('circuit-builder','basic','What does a diode do?',ARRAY['Allows current in one direction','Allows current both ways','Blocks all current','Amplifies current'],0,'Diode conducts when forward-biased.',10),
('circuit-builder','basic','What is the forward voltage drop of a silicon diode?',ARRAY['~0.7V','~0.3V','~1.2V','~0V'],0,'Silicon diode drops ~0.7V when conducting.',10),
('circuit-builder','basic','What is the forward voltage drop of a germanium diode?',ARRAY['~0.3V','~0.7V','~1.2V','~0V'],0,'Germanium diode drops ~0.3V.',10),
('circuit-builder','basic','What is a Zener diode used for?',ARRAY['Voltage regulation','Rectification','Amplification','Filtering'],0,'Zener diodes regulate voltage in reverse breakdown.',10),
('circuit-builder','basic','What is rectification?',ARRAY['Converting AC to DC','Converting DC to AC','Filtering signals','Amplifying signals'],0,'Rectifiers convert AC to pulsating DC.',10),
('circuit-builder','basic','What does a half-wave rectifier use?',ARRAY['One diode','Two diodes','Four diodes','No diode'],0,'Half-wave rectifier uses a single diode.',10);INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('circuit-builder','intermediate','What is Thevenin''s theorem?',ARRAY['Any linear network = voltage source + series resistance','Any network = current source + parallel resistance','V = IR','P = VI'],0,'Thevenin: Vth + Rth equivalent.',15),
('circuit-builder','intermediate','What is Norton''s theorem?',ARRAY['Any linear network = current source + parallel resistance','Voltage source + series resistance','V = IR','I = V/R'],0,'Norton: In || Rn equivalent.',15),
('circuit-builder','intermediate','How do you find Thevenin resistance?',ARRAY['Turn off all sources, find equivalent resistance','Measure voltage','Measure current','Short the output'],0,'Deactivate sources, then calculate Rth.',15),
('circuit-builder','intermediate','How do you find Thevenin voltage?',ARRAY['Open-circuit voltage at terminals','Short-circuit current','Equivalent resistance','Source voltage'],0,'Vth = open-circuit voltage.',15),
('circuit-builder','intermediate','How do you find Norton current?',ARRAY['Short-circuit current at terminals','Open-circuit voltage','Equivalent resistance','Source current'],0,'In = short-circuit current.',15),
('circuit-builder','intermediate','What is the relationship between Thevenin and Norton equivalents?',ARRAY['Rth = Rn, Vth = In × Rn','Rth = 2×Rn','Vth = In','In = Vth'],0,'Source transformation: Vth = In × Rn.',15),
('circuit-builder','intermediate','What is maximum power transfer?',ARRAY['Load R = source R for max power','Load R = 0','Load R = ∞','Load R = 2×source R'],0,'Max power when RL = Rth.',15),
('circuit-builder','intermediate','What is the efficiency at maximum power transfer?',ARRAY['50%','100%','25%','75%'],0,'Half the power is dissipated in source resistance.',15),
('circuit-builder','intermediate','What is superposition theorem?',ARRAY['Response = sum of responses from each source individually','Sum of all voltages','Sum of all currents','Sum of all powers'],0,'Analyze each source separately, then add.',15),
('circuit-builder','intermediate','When can you use superposition?',ARRAY['Only in linear circuits','In any circuit','Only in DC circuits','Only in AC circuits'],0,'Superposition requires linearity.',15),
('circuit-builder','intermediate','What is mesh analysis?',ARRAY['Using KVL around meshes','Using KCL at nodes','Using Ohm''s law','Using Thevenin'],0,'Mesh analysis applies KVL to each mesh.',15),
('circuit-builder','intermediate','What is nodal analysis?',ARRAY['Using KCL at nodes','Using KVL around meshes','Using Ohm''s law','Using Norton'],0,'Nodal analysis applies KCL at each node.',15),
('circuit-builder','intermediate','Which method is better for circuits with many nodes but few meshes?',ARRAY['Mesh analysis','Nodal analysis','Thevenin','Superposition'],0,'Fewer meshes = fewer mesh equations.',15),
('circuit-builder','intermediate','Which method is better for circuits with many meshes but few nodes?',ARRAY['Nodal analysis','Mesh analysis','Thevenin','Superposition'],0,'Fewer nodes = fewer nodal equations.',15),
('circuit-builder','intermediate','What is a dependent source?',ARRAY['Source controlled by another circuit variable','Independent voltage source','Battery','Current source'],0,'Dependent sources depend on voltage/current elsewhere.',15),
('circuit-builder','intermediate','What are the four types of dependent sources?',ARRAY['VCVS, VCCS, CCVS, CCCS','VCVS only','Voltage and current','AC and DC'],0,'Four types: voltage/current controlled voltage/current.',15),
('circuit-builder','intermediate','Can superposition be used with dependent sources?',ARRAY['Yes, but keep dependent sources active','No','Only with independent sources','Only with voltage sources'],0,'Dependent sources are never deactivated.',15),
('circuit-builder','intermediate','What is a transfer function?',ARRAY['Output/Input in s-domain','Output × Input','Output + Input','Output - Input'],0,'H(s) = Y(s)/X(s).',15),
('circuit-builder','intermediate','What is the impedance of a resistor?',ARRAY['R','1/(sC)','sL','1/R'],0,'Resistor impedance = R (frequency independent).',15),
('circuit-builder','intermediate','What is the impedance of a capacitor in s-domain?',ARRAY['1/(sC)','sC','sL','R'],0,'Capacitor: Z = 1/(sC).',15),
('circuit-builder','intermediate','What is the impedance of an inductor in s-domain?',ARRAY['sL','1/(sL)','1/(sC)','R'],0,'Inductor: Z = sL.',15),
('circuit-builder','intermediate','What is the impedance of a resistor at DC?',ARRAY['R','0','∞','1/R'],0,'Resistor impedance is always R.',15),
('circuit-builder','intermediate','What is the impedance of a capacitor at DC?',ARRAY['∞ (open)','0 (short)','R','1/(sC)'],0,'At DC (f=0), Xc → ∞.',15),
('circuit-builder','intermediate','What is the impedance of an inductor at DC?',ARRAY['0 (short)','∞ (open)','R','sL'],0,'At DC (f=0), Xl → 0.',15),
('circuit-builder','intermediate','What is the impedance of a capacitor at very high frequency?',ARRAY['0 (short)','∞ (open)','R','1/(sC)'],0,'At f→∞, Xc → 0.',15),
('circuit-builder','intermediate','What is the impedance of an inductor at very high frequency?',ARRAY['∞ (open)','0 (short)','R','sL'],0,'At f→∞, Xl → ∞.',15),
('circuit-builder','intermediate','What is a low-pass filter?',ARRAY['Passes low frequencies, attenuates high','Passes high, attenuates low','Passes all','Attenuates all'],0,'LPF cutoff: frequencies below fc pass.',15),
('circuit-builder','intermediate','What is a high-pass filter?',ARRAY['Passes high frequencies, attenuates low','Passes low, attenuates high','Passes all','Attenuates all'],0,'HPF cutoff: frequencies above fc pass.',15),
('circuit-builder','intermediate','What is a band-pass filter?',ARRAY['Passes a range of frequencies','Passes all frequencies','Blocks all frequencies','Passes DC only'],0,'BPF passes frequencies between f_low and f_high.',15),
('circuit-builder','intermediate','What is a band-stop filter?',ARRAY['Blocks a range of frequencies','Passes a range','Passes all','Blocks all'],0,'BSF (notch filter) rejects a band.',15),
('circuit-builder','intermediate','What is the cutoff frequency of an RC low-pass filter?',ARRAY['f = 1/(2πRC)','f = 2πRC','f = RC','f = 1/(RC)'],0,'Cutoff: fc = 1/(2πRC).',15),
('circuit-builder','intermediate','What is the cutoff frequency of an RL high-pass filter?',ARRAY['f = R/(2πL)','f = 2πL/R','f = L/R','f = RL'],0,'Cutoff: fc = R/(2πL).',15),
('circuit-builder','intermediate','What is the roll-off rate of a first-order filter?',ARRAY['-20 dB/decade','-40 dB/decade','-10 dB/decade','-60 dB/decade'],0,'First-order: -20 dB/decade or -6 dB/octave.',15),
('circuit-builder','intermediate','What is the roll-off rate of a second-order filter?',ARRAY['-40 dB/decade','-20 dB/decade','-60 dB/decade','-10 dB/decade'],0,'Second-order: -40 dB/decade.',15),
('circuit-builder','intermediate','What is the Q factor of a filter?',ARRAY['Measure of selectivity/resonance sharpness','Quality of components','Power factor','Efficiency'],0,'Q = fc/BW (center freq / bandwidth).',15),
('circuit-builder','intermediate','What is bandwidth?',ARRAY['Range of frequencies passed','Single frequency','Maximum frequency','Minimum frequency'],0,'BW = f_high - f_low.',15),
('circuit-builder','intermediate','What is resonance in an RLC circuit?',ARRAY['Xl = Xc, impedance is purely resistive','Maximum resistance','Minimum current','Maximum voltage'],0,'At resonance, Xl = Xc, Z = R.',15),
('circuit-builder','intermediate','What is the resonant frequency of an RLC circuit?',ARRAY['f = 1/(2π√(LC))','f = 2π√(LC)','f = LC','f = 1/(LC)'],0,'Resonance: fr = 1/(2π√(LC)).',15),
('circuit-builder','intermediate','What is the impedance at resonance in a series RLC circuit?',ARRAY['R (minimum)','∞','0','Xl'],0,'At resonance, Z = R (minimum impedance).',15),
('circuit-builder','intermediate','What is the impedance at resonance in a parallel RLC circuit?',ARRAY['R (maximum)','0','∞','Xc'],0,'At parallel resonance, Z = R (maximum).',15),
('circuit-builder','intermediate','What happens to current at series resonance?',ARRAY['Maximum','Minimum','Zero','Infinity'],0,'Z is minimum, so current is maximum.',15),
('circuit-builder','intermediate','What happens to current at parallel resonance?',ARRAY['Minimum','Maximum','Zero','Infinity'],0,'Z is maximum, so current is minimum.',15),
('circuit-builder','intermediate','What is a Bode plot?',ARRAY['Magnitude and phase vs frequency','Time vs voltage','Current vs voltage','Power vs time'],0,'Bode plots show frequency response.',15),
