('circuit-builder','intermediate','What is the phase margin?',ARRAY['How much phase can change before instability','Gain at cutoff','Maximum phase','Minimum phase'],0,'Phase margin measured at unity gain.',15),
('circuit-builder','intermediate','What is a decibel (dB)?',ARRAY['20 log₁₀(ratio) for voltage','10 log₁₀(ratio)','Linear ratio','Power ratio'],0,'Voltage gain in dB: 20 log₁₀(Vout/Vin).',15),
('circuit-builder','intermediate','What is the dB formula for power ratio?',ARRAY['10 log₁₀(Pout/Pin)','20 log₁₀(Pout/Pin)','Pout/Pin','log₂(Pout/Pin)'],0,'Power gain in dB: 10 log₁₀(Pout/Pin).',15),
('circuit-builder','intermediate','What is a coupling capacitor used for?',ARRAY['Blocking DC, passing AC','Blocking AC','Passing DC','Storing charge'],0,'Coupling caps block DC between stages.',15),
('circuit-builder','intermediate','What is a bypass capacitor used for?',ARRAY['Shunting AC noise to ground','Blocking DC','Passing DC','Increasing voltage'],0,'Bypass caps short AC noise to ground.',15),
('circuit-builder','intermediate','What is the input impedance of an ideal op-amp?',ARRAY['∞','0','1Ω','100Ω'],0,'Ideal op-amp has infinite input impedance.',15);INSERT INTO module_questions (module_id, level, question, options, correct_index, explanation, xp_reward) VALUES
('circuit-builder','advanced','What is the Miller effect?',ARRAY['Input capacitance multiplied by (1+Av)','Output capacitance doubled','Input resistance halved','Gain bandwidth product'],0,'Miller: Cin_effective = Cin × (1 + |Av|).',20),
('circuit-builder','advanced','What is the gain-bandwidth product (GBW)?',ARRAY['Gain × Bandwidth = constant','Gain + Bandwidth','Gain / Bandwidth','Gain² × Bandwidth'],0,'GBW is constant for an op-amp.',20),
('circuit-builder','advanced','What is the slew rate of an op-amp?',ARRAY['Maximum rate of change of output voltage','Maximum gain','Maximum input voltage','Maximum frequency'],0,'Slew rate in V/µs limits large-signal bandwidth.',20),
('circuit-builder','advanced','What causes slew rate limiting?',ARRAY['Internal compensation capacitor charging','Input impedance','Power supply','Feedback resistor'],0,'Compensation cap limits dV/dt.',20),
('circuit-builder','advanced','What is the common-mode rejection ratio (CMRR)?',ARRAY['Differential gain / Common-mode gain','Open-loop gain','Slew rate','Input bias current'],0,'CMRR = Adm/Acm, ideally ∞.',20),
('circuit-builder','advanced','What is the input offset voltage?',ARRAY['Voltage needed to zero the output','Maximum input voltage','Minimum input voltage','Supply voltage'],0,'Offset voltage nulls output when inputs are equal.',20),
('circuit-builder','advanced','What is the input bias current?',ARRAY['DC current into op-amp inputs','AC input current','Output current','Supply current'],0,'Bias current flows into both inputs.',20),
('circuit-builder','advanced','What is the difference between inverting and non-inverting op-amp?',ARRAY['Non-inverting has positive gain and high input Z','Inverting has positive gain','No difference','Inverting has higher gain'],0,'Non-inverting: +gain, high Zin; inverting: -gain, Zin = Rin.',20),
('circuit-builder','advanced','Design a summing amplifier with 3 inputs. What is Vout?',ARRAY['-(Rf/R1·V1 + Rf/R2·V2 + Rf/R3·V3)','V1+V2+V3','Rf·(V1+V2+V3)','-(V1+V2+V3)'],0,'Inverting summer: Vout = -Σ(Rf/Ri·Vi).',20),
('circuit-builder','advanced','Design a difference amplifier. What is Vout?',ARRAY['(R2/R1)×(V2-V1)','V2-V1','R2×(V1+V2)','(V1-V2)/R1'],0,'Diff amp: Vout = (R2/R1)(V2-V1).',20),
('circuit-builder','advanced','What is an instrumentation amplifier?',ARRAY['High-precision differential amplifier with high CMRR','Buffer amplifier','Summing amplifier','Power amplifier'],0,'Instrumentation amps have high CMRR and gain.',20),
('circuit-builder','advanced','What is a Schmitt trigger using op-amp?',ARRAY['Comparator with hysteresis','Unity gain buffer','Integrator','Differentiator'],0,'Positive feedback creates hysteresis.',20),
('circuit-builder','advanced','Design an op-amp integrator. What component is in the feedback path?',ARRAY['Capacitor','Resistor','Inductor','Diode'],0,'Integrator: capacitor in feedback.',20),
('circuit-builder','advanced','Design an op-amp differentiator. What component is in the input path?',ARRAY['Capacitor','Resistor','Inductor','Diode'],0,'Differentiator: capacitor at input, resistor in feedback.',20),
('circuit-builder','advanced','What is a Wien bridge oscillator?',ARRAY['RC oscillator for sine waves','LC oscillator','Crystal oscillator','Relaxation oscillator'],0,'Wien bridge uses RC network for sine wave generation.',20),
('circuit-builder','advanced','What is the frequency of a Wien bridge oscillator?',ARRAY['f = 1/(2πRC)','f = 2πRC','f = RC','f = 1/(RC)'],0,'Wien bridge: f = 1/(2πRC).',20),
('circuit-builder','advanced','What is the Barkhausen criterion for oscillation?',ARRAY['Loop gain ≥ 1 and phase shift = 360°','Gain > 0','Phase = 0','Gain = 0'],0,'|Aβ| ≥ 1 and ∠Aβ = 2nπ.',20),
('circuit-builder','advanced','What is a phase-shift oscillator?',ARRAY['RC network providing 180° phase shift','LC oscillator','Crystal oscillator','Wien bridge'],0,'Three RC stages give 180°, plus op-amp inversion = 360°.',20),
('circuit-builder','advanced','What is a Colpitts oscillator?',ARRAY['LC oscillator with capacitive divider','RC oscillator','Crystal oscillator','Relaxation oscillator'],0,'Colpitts uses a capacitive voltage divider in the tank.',20),
('circuit-builder','advanced','What is a Hartley oscillator?',ARRAY['LC oscillator with tapped inductor','RC oscillator','Crystal oscillator','Colpitts variant'],0,'Hartley uses a tapped inductor in the tank circuit.',20),
('circuit-builder','advanced','What is a crystal oscillator?',ARRAY['Uses piezoelectric crystal for high stability','Uses RC network','Uses LC tank','Uses op-amp'],0,'Crystal oscillators are very stable (ppm range).',20),
('circuit-builder','advanced','What is the equivalent circuit of a crystal?',ARRAY['Series RLC with parallel C','Just a capacitor','Just an inductor','Just a resistor'],0,'Crystal: series RLC branch with parallel capacitance.',20),
('circuit-builder','advanced','What is a relaxation oscillator?',ARRAY['Uses charging/discharging of RC','Uses LC tank','Uses crystal','Uses op-amp integrator'],0,'Relaxation oscillators use comparators + RC.',20),
('circuit-builder','advanced','What is a multivibrator?',ARRAY['Two-state circuit generating square waves','Single amplifier','Filter circuit','Oscillator with crystal'],0,'Astable, monostable, bistable multivibrators.',20),
('circuit-builder','advanced','What is an astable multivibrator?',ARRAY['Free-running oscillator (no stable state)','One stable state','Two stable states','No output'],0,'Astable continuously oscillates.',20),
